import {removeBorderBackground,guessBackground} from '../slice.mjs';
import {mountSavedLibrary} from '../saved-library-ui.mjs';
import {VFX_RESOURCE_FORMAT,detectSheetGrid,sheetGridRects,frameOrder,validateVfxResource} from './sheet-model.mjs';
const pause=()=>new Promise(resolve=>setTimeout(resolve,0));
const canvas=(w,h)=>Object.assign(document.createElement('canvas'),{width:w,height:h});
const image=src=>new Promise((ok,no)=>{const im=new Image();im.onload=()=>ok(im);im.onerror=()=>no(Error('Không đọc được ảnh VFX'));im.src=src});
const number=el=>Number(el.value.trim().replace(',','.'));
export function mountVfxSheetImport({onSelect,beforeOpen,message,download}){
 const $=id=>document.getElementById(id),dialog=document.createElement('dialog');dialog.id='vfxSheetDialog';dialog.innerHTML=`<header><strong>Tách ảnh VFX thành chuỗi frame</strong><button id="vfxSheetCancel" type="button">Đóng / hủy</button></header><div class="vfx-import-body"><p id="vfxSheetInfo" role="status"></p><label>Tên bộ ảnh<input id="vfxSheetName" maxlength="150"></label><canvas id="vfxSheetCanvas" aria-label="Chạm một ô để chọn hoặc bỏ khung hình"></canvas><div class="pair"><label>Cách chia<select id="vfxSheetMode"><option value="auto">Tự nhận lưới từ khoảng trống</option><option value="grid">Lưới tự nhập</option><option value="single">Giữ một ảnh</option></select></label><label>Nền ảnh<select id="vfxSheetBackground"><option value="auto">Tự bỏ nền phẳng ở mép ảnh</option><option value="keep">Giữ nguyên alpha / màu ảnh</option></select></label><label>Số cột<input id="vfxSheetColumns" type="number" min="1" max="128" value="1"></label><label>Số hàng<input id="vfxSheetRows" type="number" min="1" max="128" value="1"></label></div><button id="vfxSheetDetect" type="button">Nhận lại lưới tự động</button><details><summary>Lề và khoảng cách ô (pixel ảnh gốc)</summary><div class="pair"><label>Lề ngang<input id="vfxSheetMarginX" type="number" min="0" value="0"></label><label>Lề dọc<input id="vfxSheetMarginY" type="number" min="0" value="0"></label><label>Khe ngang<input id="vfxSheetGapX" type="number" min="0" value="0"></label><label>Khe dọc<input id="vfxSheetGapY" type="number" min="0" value="0"></label></div></details><div class="pair"><label>Frame mỗi giây<input id="vfxSheetFps" type="text" inputmode="decimal" value="12"></label><label>Thứ tự phát<select id="vfxSheetOrder"><option value="row">Trái → phải, trên → dưới</option><option value="column">Trên → dưới, trái → phải</option><option value="reverse">Đảo thứ tự theo hàng</option></select></label></div><label><input id="vfxSheetSkipEmpty" type="checkbox" checked> Mặc định bỏ ô trống</label><p class="hint">Chạm ô hoặc thumbnail để chọn/bỏ riêng từng frame. Các ô giữ chung canvas và điểm neo; không phóng to từng mảnh khiến hoạt ảnh bị nhảy. Ảnh không có khoảng trống hoặc bị dính các frame cần nhập số hàng/cột. Ảnh đơn vẫn dùng được.</p><div class="vfx-sheet-preview"><canvas id="vfxSheetFramePreview" width="180" height="180"></canvas><p id="vfxSheetCount"></p></div><div id="vfxSheetFrames" aria-label="Các khung hình đã nhận diện"></div><label><input id="vfxSheetSave" type="checkbox" checked> Tự lưu ảnh gốc và bộ frame vào thư viện</label><label><input id="vfxSheetAdd" type="checkbox" checked> Thêm bộ này vào skill đang chọn</label><p class="hint">Thư viện lưu trong trình duyệt/thiết bị này (IndexedDB), không tự đồng bộ. Dùng Sao lưu toàn bộ thư viện để chuyển máy hoặc trước khi xóa dữ liệu.</p></div><footer><p id="vfxSheetStatus" role="status"></p><button id="vfxSheetApply" class="primary" type="button">Dùng bộ frame đã chọn</button></footer>`;document.body.append(dialog);
 const style=document.createElement('link');style.rel='stylesheet';style.href=new URL('sheet-import.css',import.meta.url);document.head.append(style);
 $('uploadEffect').textContent='Tải ảnh / sprite sheet VFX · tự tách';
 let original=null,sourceImage=null,analysis=null,rects=[],selected=new Set(),current=null,token=0,abort=null,request=0,lastFrame=-1,processing=false,selectionContext=null;
 const status=text=>$('vfxSheetStatus').textContent=text,safe=fn=>async(...args)=>{try{await fn(...args)}catch(e){$('vfxSheetApply').disabled=true;status(e.message);message('Ảnh VFX: '+e.message)}};
 const settings=()=>({columns:number($('vfxSheetColumns')),rows:number($('vfxSheetRows')),marginX:number($('vfxSheetMarginX')),marginY:number($('vfxSheetMarginY')),gapX:number($('vfxSheetGapX')),gapY:number($('vfxSheetGapY')),fps:number($('vfxSheetFps')),order:$('vfxSheetOrder').value,background:$('vfxSheetBackground').value,skipEmpty:$('vfxSheetSkipEmpty').checked});
 const ordered=()=>frameOrder(rects,selected,$('vfxSheetOrder').value);
 function drawCell(ctx,r,w,h){ctx.clearRect(0,0,w,h);if(!analysis)return;const maxW=Math.max(...rects.map(r=>r.w)),maxH=Math.max(...rects.map(r=>r.h)),scale=Math.min(w/maxW,h/maxH)*.9;ctx.drawImage(analysis.canvas,r.x*analysis.ratio,r.y*analysis.ratio,r.w*analysis.ratio,r.h*analysis.ratio,(w-maxW*scale)/2,(h-maxH*scale)/2,r.w*scale,r.h*scale)}
 function drawSheet(){const cv=$('vfxSheetCanvas'),ctx=cv.getContext('2d');cv.width=analysis.canvas.width;cv.height=analysis.canvas.height;ctx.drawImage(analysis.canvas,0,0);ctx.font=Math.max(10,Math.round(cv.width/45))+'px system-ui';ctx.lineWidth=Math.max(1,cv.width/500);for(const r of rects){ctx.strokeStyle=selected.has(r.index)?'#d3ed92':'#8da0b6';ctx.strokeRect(r.x*analysis.ratio,r.y*analysis.ratio,r.w*analysis.ratio,r.h*analysis.ratio);ctx.fillStyle=selected.has(r.index)?'#d3ed92':'#8da0b6';ctx.fillText(String(r.index+1),r.x*analysis.ratio+4,r.y*analysis.ratio+15)}}
 function renderSelection(){const order=ordered();$('vfxSheetApply').disabled=processing||!order.length;$('vfxSheetCount').textContent=order.length+' / '+rects.length+' frame · '+(order.length/(number($('vfxSheetFps'))||12)).toFixed(2)+' s · các frame giữ cùng tỷ lệ';drawSheet();$('vfxSheetFrames').replaceChildren(...rects.map(r=>{const b=document.createElement('button');b.type='button';b.dataset.frame=String(r.index);b.setAttribute('aria-pressed',String(selected.has(r.index)));b.setAttribute('aria-label','Ô '+(r.index+1)+(r.empty?' trống':'')+(selected.has(r.index)?' đang chọn':''));const cv=canvas(88,72),label=document.createElement('span');drawCell(cv.getContext('2d'),r,88,72);label.textContent='Ô '+(r.index+1)+(r.empty?' · trống':'')+(selected.has(r.index)?' ✓':'');b.append(cv,label);b.onclick=()=>{if(processing)return;selected.has(r.index)?selected.delete(r.index):selected.add(r.index);renderSelection()};return b}));lastFrame=-1}
 async function analyze(){if(!original)return;const own=token,ratio=Math.min(1,Math.sqrt(2_000_000/(original.naturalWidth*original.naturalHeight))),cv=canvas(Math.max(1,Math.round(original.naturalWidth*ratio)),Math.max(1,Math.round(original.naturalHeight*ratio))),ctx=cv.getContext('2d',{willReadFrequently:true});ctx.drawImage(original,0,0,cv.width,cv.height);const data=ctx.getImageData(0,0,cv.width,cv.height),background=$('vfxSheetBackground').value==='auto'?guessBackground(data.data,cv.width,cv.height):null;await pause();if(own!==token)return;const result=removeBorderBackground(data.data,cv.width,cv.height,{background,tolerance:18});data.data.set(result.pixels);ctx.putImageData(data,0,0);analysis={canvas:cv,ratio,pixels:data.data,background};}
 function updateGrid(reset=true){if(!analysis)return;const s=settings();if(!Number.isFinite(s.fps)||s.fps<1||s.fps>60)throw Error('FPS từ 1 đến 60');rects=sheetGridRects({...s,width:sourceImage.width,height:sourceImage.height}).map(r=>{let solid=0;const x0=Math.max(0,Math.floor(r.x*analysis.ratio)),y0=Math.max(0,Math.floor(r.y*analysis.ratio)),x1=Math.min(analysis.canvas.width,Math.ceil((r.x+r.w)*analysis.ratio)),y1=Math.min(analysis.canvas.height,Math.ceil((r.y+r.h)*analysis.ratio));for(let y=y0;y<y1&&solid<4;y++)for(let x=x0;x<x1;x++)if(analysis.pixels[(y*analysis.canvas.width+x)*4+3]>16)solid++;return {...r,empty:solid<4}});if(reset)selected=new Set(rects.filter(r=>!s.skipEmpty||!r.empty).map(r=>r.index));renderSelection();status(rects.length>1?'Kiểm tra ô cắt và thứ tự trước khi dùng.':'Đang giữ một ảnh. Nếu đây là sprite sheet, nhập số hàng/cột để chia.');}
 async function detect(){await analyze();if(!analysis)return;const found=detectSheetGrid(analysis.pixels,analysis.canvas.width,analysis.canvas.height);$('vfxSheetColumns').value=found.columns;$('vfxSheetRows').value=found.rows;for(const id of ['MarginX','MarginY','GapX','GapY'])$('vfxSheet'+id).value=0;updateGrid();$('vfxSheetInfo').textContent=sourceImage.width+' × '+sourceImage.height+' px · '+(found.confidence==='gaps'?'Nhận diện '+found.columns+' cột × '+found.rows+' hàng.':'Chưa thấy lưới rõ; đang giữ 1 ảnh, có thể nhập lưới thủ công.');}
 function play(now){if(!dialog.open)return;const order=ordered(),fps=number($('vfxSheetFps'))||12,index=order.length?Math.floor(now/1000*fps)%order.length:-1;if(index!==lastFrame){const ctx=$('vfxSheetFramePreview').getContext('2d');if(index>=0)drawCell(ctx,order[index],180,180);else ctx.clearRect(0,0,180,180);lastFrame=index}request=requestAnimationFrame(play)}
 async function openSource(source,{context=null}={}){await beforeOpen?.();token++;abort?.abort();selectionContext=context;original=null;sourceImage=structuredClone(source);analysis=null;rects=[];selected.clear();$('vfxSheetFrames').replaceChildren();$('vfxSheetInfo').textContent='Đang đọc ảnh';$('vfxSheetAdd').parentElement.lastChild.textContent=context?' Thay ảnh của mốc đang chọn, giữ thời gian / vị trí':' Thêm bộ này vào skill đang chọn';$('vfxSheetName').value=source.name.replace(/\.[^.]+$/,'').slice(0,150)||'Hiệu ứng riêng';$('vfxSheetMode').value='auto';$('vfxSheetBackground').value='auto';$('vfxSheetFps').value=12;$('vfxSheetOrder').value='row';$('vfxSheetSkipEmpty').checked=true;$('vfxSheetSave').checked=true;$('vfxSheetAdd').checked=true;$('vfxSheetApply').disabled=true;status('Đang phân tích ảnh…');if(!dialog.open)dialog.showModal();const own=token,im=await image(source.src);if(own!==token)return;if(im.naturalWidth>8192||im.naturalHeight>8192||im.naturalWidth*im.naturalHeight>16777216)throw Error('Ảnh tối đa 8192 px mỗi chiều / 16 triệu pixel');original=im;sourceImage.width=im.naturalWidth;sourceImage.height=im.naturalHeight;await detect();cancelAnimationFrame(request);request=requestAnimationFrame(play);}
 async function extract(){const s=settings(),order=ordered(),name=$('vfxSheetName').value.trim();if(!name)throw Error('Nhập tên bộ VFX');if(!order.length)throw Error('Chọn ít nhất một frame');const commonW=Math.max(...rects.map(r=>r.w)),commonH=Math.max(...rects.map(r=>r.h)),resize=Math.min(1,2048/commonW,2048/commonH),w=Math.max(1,Math.round(commonW*resize)),h=Math.max(1,Math.round(commonH*resize)),cv=canvas(w,h),ctx=cv.getContext('2d',{willReadFrequently:true}),frames=[];let bytes=0;for(let i=0;i<order.length;i++){if(abort.signal.aborted)throw Error('Đã hủy tách ảnh');const r=order[i];ctx.clearRect(0,0,w,h);ctx.drawImage(original,r.x,r.y,r.w,r.h,0,0,r.w*resize,r.h*resize);if(analysis.background){const data=ctx.getImageData(0,0,w,h),out=removeBorderBackground(data.data,w,h,{background:analysis.background,tolerance:18});data.data.set(out.pixels);ctx.putImageData(data,0,0)}const src=cv.toDataURL('image/png');bytes+=src.length;if(bytes>32*1024*1024)throw Error('Bộ frame quá 32 MB; hãy chọn ít frame hơn hoặc chia bộ');const display=Math.min(1,400/w,400/h);frames.push({src,w:w*display,h:h*display,ax:.5,ay:.5,duration:1/s.fps});status('Đang tách '+(i+1)+' / '+order.length+' frame…');await pause()}const id='vfx_'+crypto.randomUUID();return validateVfxResource({format:VFX_RESOURCE_FORMAT,id,name,sourceImage:structuredClone(sourceImage),slice:{...s,selected:order.map(r=>r.index)},effect:{id,name,group:frames.length===1?'image':'frames',frames,source:'Ảnh riêng · đã tách trong Studio',preview:frames.length+' frame · '+s.fps+' FPS · điểm neo chung'}})}
 const recut=document.createElement('button');recut.id='vfxRecut';recut.type='button';recut.textContent='Tách lại ảnh gốc thành bộ mới';recut.disabled=true;$('effectFile').after(recut);
 $('vfxSheetName').onchange=safe(()=>updateGrid(false));
 const shelf=mountSavedLibrary({kind:'vfx-assets',label:'Ảnh VFX & bộ frame',anchor:recut,getProject:()=>current,getName:r=>r.name,portable:()=>structuredClone(validateVfxResource(current)),beforeSave:()=>{if(!current)throw Error('Tải và tách ảnh hoặc mở một bộ đã lưu trước')},load:async r=>{await beforeOpen?.();current=structuredClone(validateVfxResource(r));recut.disabled=false;await onSelect(current,{add:false})},message,download});
 $('uploadEffect').addEventListener('click',safe(async()=>{await beforeOpen?.();$('effectFile').click()}));$('effectFile').addEventListener('change',safe(async()=>{try{const f=$('effectFile').files[0];if(!f)return;if(!['image/png','image/webp','image/jpeg'].includes(f.type)||f.size>8*1024*1024)throw Error('PNG/WebP/JPG tối đa 8 MB');const src=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=()=>no(Error('Không đọc được file'));r.readAsDataURL(f)});await openSource({src,name:f.name.slice(0,250)})}finally{$('effectFile').value=''}}));recut.onclick=safe(()=>current&&openSource(current.sourceImage));
 for(const id of ['Columns','Rows','MarginX','MarginY','GapX','GapY'])$('vfxSheet'+id).onchange=safe(()=>{$('vfxSheetMode').value='grid';$('vfxSheetApply').disabled=true;updateGrid()});$('vfxSheetMode').onchange=safe(async()=>{if($('vfxSheetMode').value==='auto')return detect();if($('vfxSheetMode').value==='single'){for(const id of ['Columns','Rows'])$('vfxSheet'+id).value=1;for(const id of ['MarginX','MarginY','GapX','GapY'])$('vfxSheet'+id).value=0}updateGrid()});$('vfxSheetBackground').onchange=safe(async()=>{if($('vfxSheetMode').value==='auto')await detect();else{await analyze();updateGrid()}});$('vfxSheetSkipEmpty').onchange=safe(()=>updateGrid());$('vfxSheetOrder').onchange=safe(()=>renderSelection());$('vfxSheetFps').onchange=safe(()=>{if(number($('vfxSheetFps'))<1||number($('vfxSheetFps'))>60||!Number.isFinite(number($('vfxSheetFps'))))throw Error('FPS từ 1 đến 60');renderSelection()});$('vfxSheetDetect').onclick=safe(()=>{$('vfxSheetMode').value='auto';return detect()});
 $('vfxSheetCanvas').onclick=e=>{if(!analysis||processing)return;const cv=$('vfxSheetCanvas'),bounds=cv.getBoundingClientRect(),x=(e.clientX-bounds.left)/bounds.width*sourceImage.width,y=(e.clientY-bounds.top)/bounds.height*sourceImage.height,r=rects.find(r=>x>=r.x&&x<r.x+r.w&&y>=r.y&&y<r.y+r.h);if(r){selected.has(r.index)?selected.delete(r.index):selected.add(r.index);renderSelection()}};
 const close=()=>{if($('vfxSheetCancel').disabled)return;abort?.abort();dialog.close()};$('vfxSheetCancel').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close()});dialog.addEventListener('close',()=>{token++;abort?.abort();cancelAnimationFrame(request);original=null;analysis=null;rects=[]});
 $('vfxSheetApply').onclick=safe(async()=>{
  if(processing)return;const input=settings();sheetGridRects({...input,width:sourceImage.width,height:sourceImage.height});if(!Number.isFinite(input.fps)||input.fps<1||input.fps>60)throw Error('FPS từ 1 đến 60');if(!$('vfxSheetName').value.trim())throw Error('Nhập tên bộ VFX');processing=true;abort=new AbortController();$('vfxSheetApply').disabled=true;
  const controls=[...dialog.querySelectorAll('input,select,button')].filter(el=>!['vfxSheetCancel','vfxSheetApply'].includes(el.id));for(const el of controls)el.disabled=true;
  try{
   const resource=await extract();if(abort.signal.aborted)return;current=resource;recut.disabled=false;let saved=false,warning='';$('vfxSheetCancel').disabled=true;
   if($('vfxSheetSave').checked)try{await shelf.save();saved=true}catch(e){warning=' Chưa lưu thư viện: '+e.message+'; hãy tải bản sao project.'}
   const add=$('vfxSheetAdd').checked,result=await onSelect(current,{add,context:selectionContext});dialog.close();message('Đã tách '+resource.effect.frames.length+' frame.'+(saved?' Đã lưu ảnh gốc + bộ frame vào thư viện.':'')+(result?.replaced?' Đã thay ảnh mốc, giữ thời gian / vị trí.':'')+(add&&result?.added===false?' Tạo/chọn skill rồi bấm Thêm VFX để dùng.':'')+warning);
  }finally{processing=false;abort=null;for(const el of controls)el.disabled=false;$('vfxSheetCancel').disabled=false;if(dialog.open)renderSelection()}
 });
 return {shelf,openSource,getResource:()=>current};
}
